  .dev-tools-info-container {
    width: 100%;
  }

  .dev-tools-info-body {
    padding: 16px;
  }

  .dev-tools-info-header {
    height: 48px;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 8px;
    border-bottom: 1px solid var(--color-gray-alpha-400);
  }

