      color: var(--color-gray-1000);
    }
  }

  .dev-tools-info-title {
    color: var(--color-gray-1000);
    font-size: var(--size-14);
    font-weight: 500;
    line-height: var(--size-20);
    margin: 0;
  }

  .dev-tools-info-section-title {
