interface ProductImageHistoryProps {
  productId: string;
  refreshToken: number;
  onUseImage: (url: string) => void;
}

export function ProductImageHistory({ productId, refreshToken, onUseImage }: ProductImageHistoryProps) {
  const [versions, setVersions] = useState<ImageVersion[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!productId) return;
    let cancelled = false;
    (async () => {
      try {
        setLoading(true);
        const accessToken = await getValidAccessToken().catch(() => null);
        const response = await fetch(`/api/admin-product-images?productId=${encodeURIComponent(productId)}`, {
          headers: Object.fromEntries(
            Object.entries({
              accept: "application/json",
              Authorization: accessToken ? `Bearer ${accessToken}` : undefined,
            }).filter(([, v]) => v != null)
          ) as HeadersInit,
          cache: "no-store",
        });
        if (!response.ok) {
          throw new Error(await response.text());
        }
        const json = await response.json();
        if (!cancelled && Array.isArray(json?.versions)) {
          setVersions(json.versions as ImageVersion[]);
        }
      } catch (error) {
        if (!cancelled) {
          console.warn("product image history fetch failed", error);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [productId, refreshToken]);

  const makeCurrent = async (versionId: string) => {
    try {
      const accessToken = await getValidAccessToken().catch(() => null);
      const response = await fetch("/api/admin-product-images", {
        method: "POST",
        headers: Object.fromEntries(
          Object.entries({
            "content-type": "application/json",
            Authorization: accessToken ? `Bearer ${accessToken}` : undefined,
          }).filter(([, v]) => v != null)
        ) as HeadersInit,
        body: JSON.stringify({
          op: "revert",
          productId,
          versionId,
        }),
      });
      if (!response.ok) {
        throw new Error(await response.text());
      }
      const json = await response.json();
      const current = json?.current as ImageVersion | undefined;
      if (current?.publicUrl) {
        onUseImage(current.publicUrl);
        setVersions((prev) => prev.map((item) => ({ ...item, isCurrent: item.id === current.id })));
        toast("Primary image updated", { variant: "success" });
      }
    } catch (error) {
      toast(error instanceof Error ? error.message : String(error), { variant: "error" });
    }
  };

  if (!productId) return null;

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold">Image history</h3>
        {loading ? <span className="text-xs text-muted-foreground">Loading...</span> : null}
      </div>
      {versions.length === 0 ? (
        <div className="text-xs text-muted-foreground">No previous versions yet.</div>
      ) : (
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {versions.map((version) => (
            <div
              key={version.id}
              className={`rounded-lg border p-2 text-xs ${version.isCurrent ? "border-primary" : "border-border"}`}
            >
              <div className="relative aspect-square overflow-hidden rounded">
                <Image
                  src={version.publicUrl || "/og.svg"}
                  alt="Version history preview"
                  fill
                  sizes="(max-width: 640px) 33vw, (max-width: 1024px) 20vw, 200px"
                  className="object-cover"
                  unoptimized
                />
              </div>
              <div className="mt-2 flex flex-col gap-1">
                <span className="text-[10px] text-muted-foreground">{new Date(version.uploadedAt).toLocaleString()}</span>
                <Button
                  type="button"
                  variant={version.isCurrent ? "soft" : "secondary"}
                  disabled={version.isCurrent}
                  onClick={() => makeCurrent(version.id)}
                >
                  {version.isCurrent ? "Current" : "Use as primary"}
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import Image from "next/image";

import { UploadCloud, Trash2, Star, Link as LinkIcon, Loader2 } from "lucide-react";

import Button from "@ui/components/common/button";
import Input from "@ui/components/common/input";
import { toast } from "@ui/components/common/toast";
import { normalizeSku } from "@shared/lib/normalize";
import { getValidAccessToken } from "@shared/lib/auth";

interface ProductImagesFieldProps {
  label?: string;
  images: string[];
  onChange: (next: string[]) => void;
  slug?: string | null;
  productId?: string | null;
  sku?: string | null;
  onVersionCreated?: (payload: { id: string; publicUrl: string }) => void;
}

async function recordImageVersion(params: {
  productId: string;
  sku: string;
  path: string;
  sourceUrl: string;
  accessToken?: string | null;
  onVersionCreated?: (payload: { id: string; publicUrl: string }) => void;
}) {
  try {
    const response = await fetch("/api/admin-product-images", {
      method: "POST",
      headers: Object.fromEntries(
        Object.entries({
          "content-type": "application/json",
          Authorization: params.accessToken ? `Bearer ${params.accessToken}` : undefined,
        }).filter(([, v]) => v != null)
      ) as HeadersInit,
      body: JSON.stringify({
        op: "record",
        productId: params.productId,
        sku: params.sku,
        path: params.path,
        sourceUrl: params.sourceUrl,
      }),
    });
    if (!response.ok) return;
    const json = await response.json();
    const versionId = json?.version?.id as string | undefined;
    const versionUrl = json?.version?.publicUrl as string | undefined;
    if (versionId && versionUrl && params.onVersionCreated) {
      params.onVersionCreated({ id: versionId, publicUrl: versionUrl });
    }
  } catch (error) {
    console.warn("record image version failed", error);
  }
}

export function ProductImagesField({
  label = "Images",
  images,
  onChange,
  slug,
  productId,
  sku,
  onVersionCreated,
}: ProductImagesFieldProps) {
  const fileInput = useRef<HTMLInputElement | null>(null);
  const [manualUrl, setManualUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFiles = async (fileList: FileList | null) => {
    if (!fileList?.length) return;
    if (!productId) {
      setError("Save the product before uploading images.");
      if (fileInput.current) fileInput.current.value = "";
      return;
    }

    const file = fileList[0];
    if (!file) return;

    setUploading(true);
    setError(null);
    try {
      const accessToken = await getValidAccessToken().catch(() => null);

      const normalizedSku = normalizeSku(sku ?? undefined, slug ?? productId ?? undefined);
      if (!normalizedSku) throw new Error("Cannot derive SKU for upload");

      const ext = file.name.split(".").pop() ?? "webp";
      const uploadResponse = await fetch("/api/admin-get-upload-url", {
        method: "POST",
        headers: Object.fromEntries(
          Object.entries({
            "content-type": "application/json",
            Authorization: accessToken ? `Bearer ${accessToken}` : undefined,
          }).filter(([, v]) => v != null)
        ) as HeadersInit,
        body: JSON.stringify({
          productId,
          sku: normalizedSku,
          slug: slug || null,
          ext,
        }),
      });

      if (!uploadResponse.ok) {
        throw new Error(await uploadResponse.text());
      }

      const uploadJson = await uploadResponse.json();
      const uploadUrl = uploadJson?.uploadUrl as string | undefined;
      const publicUrl = uploadJson?.publicUrl as string | undefined;
      const storagePath = uploadJson?.path as string | undefined;

      if (!uploadUrl || !publicUrl || !storagePath) {
        throw new Error("Upload URL response missing fields");
      }

      const putResponse = await fetch(uploadUrl, {
        method: "PUT",
        headers: {
          "content-type": file.type || "application/octet-stream",
        },
        body: file,
      });
      if (!putResponse.ok) {
        throw new Error(`Upload failed: ${putResponse.status}`);
      }

      const nextImages = [publicUrl, ...images.filter((url) => url !== publicUrl)];
      onChange(nextImages);

      await recordImageVersion({
        productId,
        sku: normalizedSku,
        path: storagePath,
        sourceUrl: publicUrl,
        accessToken,
        onVersionCreated,
      });

      toast("Image uploaded", { variant: "success" });
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setUploading(false);
      if (fileInput.current) fileInput.current.value = "";
    }
  };

  const removeImage = (index: number) => {
    onChange(images.filter((_, idx) => idx !== index));
  };

  const promoteImage = (index: number) => {
    if (index <= 0) return;
    const next = [...images];
    const [selected] = next.splice(index, 1);
    next.unshift(selected);
    onChange(next);
  };

  const addManualImage = () => {
    const url = manualUrl.trim();
    if (!url) return;
    onChange([url, ...images.filter((item) => item !== url)]);
    setManualUrl("");
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center gap-3">
        <label className="text-sm font-medium">{label}</label>
        {uploading && (
          <span className="inline-flex items-center gap-1 text-xs text-muted-foreground">
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
            Uploading...
          </span>
        )}
      </div>

      <div className="flex flex-wrap gap-3">
        {images.map((url, index) => (
          <div key={`${url}-${index}`} className="relative h-28 w-28 overflow-hidden rounded-xl border border-border bg-card shadow-sm">
            <Image
              src={url || "/og.svg"}
              alt={`Product ${index + 1}`}
              fill
              sizes="112px"
              className="object-cover"
              onError={(event) => {
                event.currentTarget.src = "/og.svg";
              }}
              unoptimized
            />
            <div className="absolute inset-x-0 bottom-0 flex items-center justify-between gap-1 bg-black/60 px-2 py-1 text-[11px] text-white">
              <button
                type="button"
                className="inline-flex items-center gap-1"
                onClick={() => promoteImage(index)}
                disabled={index === 0}
              >
                <Star className={`h-3 w-3 ${index === 0 ? "text-yellow-300" : "text-white/80"}`} />
                {index === 0 ? "Primary" : "Promote"}
              </button>
              <button
                type="button"
                className="inline-flex items-center gap-1"
                onClick={() => removeImage(index)}
              >
                <Trash2 className="h-3 w-3" />
                Remove
              </button>
            </div>
          </div>
        ))}

        <button
          type="button"
          onClick={() => fileInput.current?.click()}
          className="flex h-28 w-28 flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-border bg-background text-xs text-muted-foreground transition hover:border-border/80"
          disabled={uploading || !productId}
        >
          <UploadCloud className="h-6 w-6" />
          Upload
        </button>
      </div>

      <input
        ref={fileInput}
        className="hidden"
        type="file"
        accept="image/*"
        multiple
        onChange={(event) => handleFiles(event.currentTarget.files)}
      />

      <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
        <Input
          type="url"
          placeholder="https://example.com/image.jpg"
          value={manualUrl}
          onChange={(event) => setManualUrl(event.currentTarget.value)}
        />
        <Button type="button" variant="secondary" onClick={addManualImage} disabled={!manualUrl.trim()} className="sm:w-auto">
          <LinkIcon className="mr-2 h-4 w-4" />Add by URL
        </Button>
      </div>

      {error ? <div className="text-sm text-rose-500">{error}</div> : null}
      <p className="text-xs text-muted-foreground">
        Images are stored in Supabase Storage. The first image is treated as the primary preview.
      </p>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams, usePathname } from "next/navigation";

import Section from "@ui/components/common/section";
import Card from "@ui/components/common/card";
import Button from "@ui/components/common/button";
import Input from "@ui/components/common/input";
import Skeleton from "@ui/components/common/skeleton";
import StatusBadge from "@ui/components/admin/StatusBadge";
import ProductDialog from "@ui/components/admin/ProductDialog";
import { toast } from "@ui/components/common/toast";
import { getValidAccessToken } from "@shared/lib/auth";
import { adminFetch } from "@shared/lib/api";

interface ProductRow {
  id: string;
  title: string;
  slug: string;
  price: number;
  category_slug: string | null;
  status: string | null;
  rating: number | null;
  created_at: string;
  sku?: string | null;
  images?: string[] | null;
  short_desc?: string | null;
  tags?: string[] | null;
}

interface CategoryOption {
  slug: string;
  name: string;
  color?: string | null;
}

interface FetchParams {
  q?: string;
  status?: string;
  category?: string;
  sort?: string;
  dir?: "asc" | "desc";
}

async function authorizedFetch(input: string, init?: RequestInit) {
  const accessToken = await getValidAccessToken().catch(() => null);
  const headers = new Headers(init?.headers);
  if (accessToken) headers.set("Authorization", `Bearer ${accessToken}`);
  return adminFetch(input, { ...init, headers });
}

async function fetchProducts(params: FetchParams) {
  const url = new URL("/api/ecom-products", window.location.origin);
  if (params.q) url.searchParams.set("q", params.q);
  if (params.status && params.status !== "all") {
    url.searchParams.set("status", params.status);
  }
  if (params.category && params.category !== "all") {
    url.searchParams.set("category", params.category);
  }
  if (params.sort) url.searchParams.set("sort", params.sort);
  if (params.dir) url.searchParams.set("dir", params.dir);
  url.searchParams.set("limit", "25");

  const res = await authorizedFetch(url.toString());
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const json = await res.json();
  return {
    items: Array.isArray(json?.items) ? (json.items as ProductRow[]) : [],
    total: Number(json?.total || 0),
  };
}

async function fetchCategories() {
  try {
    const res = await authorizedFetch("/api/ecom-categories");
    if (!res.ok) return [];
    const json = await res.json();
    return Array.isArray(json?.items)
      ? (json.items as CategoryOption[])
      : [];
  } catch (error) {
    console.warn("Failed to load categories", error);
    return [];
  }
}

const CATEGORY_PALETTES = [
  "bg-[#60a5fa]",
  "bg-[#f97316]",
  "bg-[#34d399]",
  "bg-[#a855f7]",
  "bg-[#facc15]",
  "bg-[#f472b6]",
  "bg-[#38bdf8]",
  "bg-[#fb7185]",
];

function pickCategoryDot(slug: string | null) {
  const base = slug ?? "";
  if (!base.length) return "bg-border";
  let hash = 0;
  for (let i = 0; i < base.length; i += 1) {
    hash = base.charCodeAt(i) + ((hash << 5) - hash);
  }
  const idx = Math.abs(hash) % CATEGORY_PALETTES.length;
  return CATEGORY_PALETTES[idx];
}

export function ProductsClient() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const pathname = usePathname();

  const [query, setQuery] = useState(() => searchParams?.get("q") ?? "");
  const [status, setStatus] = useState(() => searchParams?.get("status") ?? "all");
  const [category, setCategory] = useState(() => searchParams?.get("category") ?? "all");
  const [items, setItems] = useState<ProductRow[]>([]);
  const [refreshToken, setRefreshToken] = useState(0);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [categories, setCategories] = useState<CategoryOption[]>([]);
  const normalizedCategories = useMemo(
    () => categories.map((item) => ({ ...item, color: item.color ?? undefined })),
    [categories],
  );
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState<ProductRow | null>(null);

  const dialogInitial = useMemo(() => {
    if (!editing) return undefined;
    const status: 'draft' | 'published' | 'archived' =
      editing.status === 'published' || editing.status === 'archived' ? editing.status : 'draft';
    return {
      id: editing.id,
      title: editing.title,
      slug: editing.slug,
      sku: editing.sku ?? undefined,
      price: editing.price ?? 0,
      category_slug: editing.category_slug ?? null,
      status,
      rating: editing.rating ?? undefined,
      short_desc: editing.short_desc ?? undefined,
      images: editing.images ?? undefined,
      tags: editing.tags ?? undefined,
    };
  }, [editing]);

  const statusOptions = useMemo(
    () => [
      { value: "all", label: "All statuses" },
      { value: "draft", label: "Draft" },
      { value: "published", label: "Published" },
      { value: "archived", label: "Archived" },
    ],
    [],
  );

  useEffect(() => {
    let mounted = true;
    (async () => {
      const data = await fetchCategories();
      if (mounted) setCategories(data);
    })();
    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    const params = new URLSearchParams();
    if (query) params.set("q", query);
    if (status && status !== "all") params.set("status", status);
    if (category && category !== "all") params.set("category", category);
    const search = params.toString();
    router.replace(search ? `${pathname}?${search}` : pathname, { scroll: false });
  }, [query, status, category, pathname, router]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const { items, total } = await fetchProducts({
          q: query || undefined,
          status: status || undefined,
          category: category || undefined,
          sort: "created_at",
          dir: "desc",
        });
        if (!cancelled) {
          setItems(items);
          setTotal(total);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : String(err));
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [query, status, category, refreshToken]);

  const categoryLabel = (slug: string | null) => {
    if (!slug) return "-";
    const match = categories.find((item) => item.slug === slug);
    return match?.name ?? slug;
  };

  return (
    <Section className="space-y-6 p-6">
      <div className="flex flex-wrap items-center gap-3">
        <h1 className="text-2xl font-semibold">Products</h1>
        <div className="ml-auto flex flex-wrap items-center gap-2">
          <Button onClick={() => router.push("/admin/shop/products/new")}>Add product</Button>
        </div>
      </div>

      <Card className="p-4">
        <div className="grid gap-3 md:grid-cols-[1fr_160px_160px]">
          <Input
            value={query}
            onChange={(event) => setQuery(event.currentTarget.value)}
            placeholder="Search products..."
          />
          <select
            className="h-10 rounded-md border border-border bg-background px-3 text-sm"
            value={status}
            onChange={(event) => setStatus(event.currentTarget.value)}
          >
            {statusOptions.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
          <select
            className="h-10 rounded-md border border-border bg-background px-3 text-sm"
            value={category}
            onChange={(event) => setCategory(event.currentTarget.value)}
          >
            <option value="all">All categories</option>
            {categories.map((item) => (
              <option key={item.slug} value={item.slug}>
                {item.name}
              </option>
            ))}
          </select>
        </div>
      </Card>

      {loading ? (
        <Card className="p-4">
          <div className="space-y-2">
            {Array.from({ length: 6 }).map((_, index) => (
              <Skeleton key={index} className="h-8 w-full" />
            ))}
          </div>
        </Card>
      ) : error ? (
        <Card className="p-4 text-sm text-rose-500">{error}</Card>
      ) : items.length === 0 ? (
        <Card className="p-10 text-center text-sm text-muted-foreground">
          No products found.
        </Card>
      ) : (
        <div className="overflow-x-auto">
          <table className="min-w-full border-collapse text-sm">
            <thead>
              <tr className="border-b border-border/40 text-left text-xs uppercase tracking-wide text-muted-foreground">
                <th className="py-2 pr-4">Title</th>
                <th className="py-2 pr-4">Status</th>
                <th className="py-2 pr-4">Price</th>
                <th className="py-2 pr-4">Category</th>
                <th className="py-2 pr-4">Rating</th>
                <th className="py-2 pr-4">Actions</th>
              </tr>
            </thead>
            <tbody>
              {items.map((product) => (
                <tr key={product.id} className="border-b border-border/20 transition-colors duration-150 hover:bg-card/60">
                  <td className="py-3 pr-4">
                    <div className="font-medium text-foreground">{product.title}</div>
                    <div className="text-xs text-muted-foreground">{product.slug}</div>
                  </td>
                  <td className="py-3 pr-4">
                    <StatusBadge status={product.status ?? "unknown"} />
                  </td>
                  <td className="py-3 pr-4">
                    {new Intl.NumberFormat(undefined, {
                      style: "currency",
                      currency: "EUR",
                    }).format(product.price ?? 0)}
                  </td>
                  <td className="py-3 pr-4">
                    <span className="inline-flex items-center gap-2 rounded-md border border-border px-2 py-1 text-xs">
                      <span className={`inline-block h-2 w-2 rounded-full ${pickCategoryDot(product.category_slug)}`} />
                      {categoryLabel(product.category_slug)}
                    </span>
                  </td>
                  <td className="py-3 pr-4">{product.rating ?? 0}</td>
                  <td className="py-3 pr-4">
                    <div className="flex flex-wrap gap-2">
                      <Button
                        variant="soft"
                        className="h-8 min-h-0 px-3 text-xs"
                        onClick={() => router.push(`/admin/shop/products/${product.id}`)}
                      >
                        Edit
                      </Button>
                      <Button
                        variant="ghost"
                        className="h-8 min-h-0 px-3 text-xs"
                        onClick={() => {
                          setEditing(product);
                          setDialogOpen(true);
                        }}
                      >
                        Quick edit
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="px-4 py-2 text-xs text-muted-foreground">
            Showing {items.length} of {total || items.length} items
          </div>
        </div>
      )}

      <ProductDialog
        open={dialogOpen}
        onOpenChange={(open) => {
          setDialogOpen(open);
          if (!open) setEditing(null);
        }}
        initial={dialogInitial}
        categories={normalizedCategories}
        onSaved={() => {
          toast("Saved", { variant: "success" });
          setDialogOpen(false);
          setEditing(null);
          // trigger refetch
          setRefreshToken((value) => value + 1);
        }}
      />
    </Section>
  );
}

"use client";

import { useEffect, useState } from "react";

import Section from "@ui/components/common/section";
import Card from "@ui/components/common/card";
import Input from "@ui/components/common/input";
import Button from "@ui/components/common/button";
import { supabase } from "@shared/lib/supabase";

const PAGE_SIZE = 50;

export type WebhookLogRow = {
  id: string;
  type: string;
  created_at: string;
  payload: unknown;
};

export function WebhooksClient() {
  const [rows, setRows] = useState<WebhookLogRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(0);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        setLoading(true);
        setError(null);
        const from = page * PAGE_SIZE;
        const to = from + PAGE_SIZE - 1;
        let builder: any = supabase
          .from("webhook_logs")
          .select("id,type,created_at,payload")
          .order("created_at", { ascending: false })
          .range(from, to);
        if (query.trim()) {
          builder = builder.ilike("type", `%${query.trim()}%`);
        }
        const { data, error: dbError } = await builder;
        if (dbError) throw dbError;
        if (!cancelled) {
          setRows((data as WebhookLogRow[]) ?? []);
        }
      } catch (err: any) {
        if (!cancelled) {
          setError(String(err?.message ?? err));
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [page, query]);

  useEffect(() => {
    setPage(0);
  }, [query]);

  async function purge() {
    try {
      const cutoff = new Date(Date.now() - 30 * 86_400_000).toISOString();
      const { error: rpcError } = await (supabase as any).rpc("purge_webhook_logs", { cutoff_ts: cutoff });
      if (rpcError) throw rpcError;
      setPage(0);
      const { data } = await (supabase as any)
        .from("webhook_logs")
        .select("id,type,created_at,payload")
        .order("created_at", { ascending: false })
        .range(0, PAGE_SIZE - 1);
      setRows((data as WebhookLogRow[]) ?? []);
    } catch (err: any) {
      window.alert(`Purge failed: ${String(err?.message ?? err)}`);
    }
  }

  return (
    <Section className="space-y-6 p-6">
      <Card className="p-6">
        <div className="mb-3 flex items-center gap-3">
          <h1 className="text-xl font-semibold">Webhook Logs</h1>
          <div className="ml-auto flex items-center gap-2">
            <Input
              className="h-9 w-[220px]"
              placeholder="Filter by type"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
            />
            <Button
              variant="soft"
              className="h-9 min-h-0 px-3 text-sm"
              onClick={() => setPage((value) => Math.max(0, value - 1))}
              disabled={page === 0 || loading}
            >
              Prev
            </Button>
            <span className="text-sm">Page {page + 1}</span>
            <Button
              variant="soft"
              className="h-9 min-h-0 px-3 text-sm"
              onClick={() => setPage((value) => value + 1)}
              disabled={loading}
            >
              Next
            </Button>
            <Button
              variant="soft"
              className="h-9 min-h-0 px-3 text-sm"
              onClick={purge}
              disabled={loading}
              title="Delete logs older than 30 days"
            >
              Purge &gt;30d
            </Button>
          </div>
        </div>
        {loading ? (
          <div>Loading.</div>
        ) : error ? (
          <div className="text-red-400">{error}</div>
        ) : rows.length ? (
          <div className="space-y-2">
            {rows.map((row) => (
              <div key={row.id} className="rounded border border-white/10 p-3">
                <div className="flex justify-between text-sm">
                  <span className="font-mono">{row.type}</span>
                  <span className="text-[var(--text-dim)]">{row.created_at}</span>
                </div>
                <details className="mt-1">
                  <summary className="cursor-pointer text-[var(--text-dim)]">payload</summary>
                  <pre className="whitespace-pre-wrap break-words text-xs">
                    {JSON.stringify(row.payload, null, 2)}
                  </pre>
                </details>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-sm text-[var(--text-dim)]">No rows.</div>
        )}
      </Card>
    </Section>
  );
}

