                <label className="grid gap-2 text-sm text-neutral-600">
                  Postal code
                  <input
                    className="h-11 rounded-lg border border-slate-200 px-3 text-sm shadow-sm focus:border-blue-300 focus:outline-none focus:ring-2 focus:ring-blue-200"
