"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

import { getUser } from "@shared/lib/auth";

export default function UserBadge() {
  const [email, setEmail] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const user = await getUser();
        if (active) setEmail(user?.email ?? null);
      } catch {
        if (active) setEmail(null);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  if (!email) {
    return (
      <Link
        href="/login"
        className="rounded-xl bg-[color:var(--brand,#F5D15A)] px-4 py-2 font-medium text-[color:var(--brand-fg,#1A1A1A)] transition hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-primary/50"
      >
        Log in
      </Link>
    );
  }

  return <span className="text-sm text-[var(--text-dim)]">{email}</span>;
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import {
  ChevronLeft,
  ChevronRight,
  CreditCard,
  Package,
  Pause,
  Play,
  Quote,
  Sparkles,
  Star,
  Tag,
  Truck,
} from "lucide-react";
import { cn } from "@shared/lib/cn";

type HeroVisual = "storefront" | "checkout" | "delivery" | "promo" | "reviews";

export type HeroSlide = {
  id: string;
  eyebrow?: string;
  title: string;
  description: string;
  primaryCta: { label: string; href: string };
  secondaryCta?: { label: string; href: string };
  backgroundClass?: string;
  highlights?: string[];
  metrics?: Array<{ label: string; value: string; detail?: string }>;
  visual?: HeroVisual;
};

const AUTOPLAY_INTERVAL = 6000;

export function HeroSlider({ slides }: { slides: HeroSlide[] }) {
  const safeSlides = useMemo(() => slides.filter(Boolean), [slides]);
  const [index, setIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  const slideCount = safeSlides.length;

  const goTo = useCallback(
    (next: number) => {
      if (!slideCount) return;
      setIndex((next + slideCount) % slideCount);
    },
    [slideCount],
  );

  useEffect(() => {
    if (slideCount <= 1 || isPaused) return;
    const timer = window.setInterval(() => {
      setIndex((prev) => ((prev + 1) % slideCount + slideCount) % slideCount);
    }, AUTOPLAY_INTERVAL);
    return () => window.clearInterval(timer);
  }, [isPaused, slideCount]);

  const activeSlide = safeSlides[index] ?? safeSlides[0];

  if (!activeSlide) return null;

  return (
    <section
      className={cn(
        "relative overflow-hidden text-white",
        activeSlide.backgroundClass ?? "bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900",
      )}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      onFocusCapture={() => setIsPaused(true)}
      onBlurCapture={() => setIsPaused(false)}
    >
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.12),transparent_55%)]" aria-hidden />
      <div className="relative mx-auto flex max-w-6xl flex-col items-center gap-6 px-6 py-8 text-center sm:gap-6 sm:py-10 lg:py-12">
        <div className="relative w-full">
          <div className="relative grid min-h-[220px] gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(260px,1fr)] lg:items-center">
            {safeSlides.map((slide, slideIndex) => (
              <article key={slide.id} className="contents" aria-hidden={slideIndex !== index}>
                <div
                  className={cn(
                    "relative mx-auto flex w-full max-w-3xl flex-col items-center transition-all duration-700 ease-out lg:items-start lg:text-left",
                    slideIndex === index
                      ? "pointer-events-auto opacity-100 translate-y-0"
                      : "hidden pointer-events-none opacity-0 translate-y-6",
                  )}
                >
                  {slide.eyebrow ? (
                    <span className="mb-4 inline-flex items-center gap-2 rounded-full bg-white/10 px-4 py-1 text-xs font-semibold uppercase tracking-[0.24em] text-white/80">
                      <Sparkles className="h-3 w-3" />
                      {slide.eyebrow}
                    </span>
                  ) : null}
                  <h1 className="text-3xl font-semibold sm:text-4xl md:text-5xl">{slide.title}</h1>
                  <p className="mt-4 text-base text-slate-200 sm:text-lg">{slide.description}</p>
                  {slide.highlights?.length ? (
                    <ul className="mt-4 flex flex-wrap justify-center gap-2 text-xs uppercase text-white/80 sm:text-sm lg:justify-start">
                      {slide.highlights.map((highlight) => (
                        <li key={`${slide.id}-${highlight}`}>
                          <span className="inline-flex items-center gap-2 rounded-full bg-white/12 px-3 py-1">
                            <span className="h-1.5 w-1.5 rounded-full bg-white/70" />
                            {highlight}
                          </span>
                        </li>
                      ))}
                    </ul>
                  ) : null}
                  <div className="mt-6 flex flex-wrap items-center justify-center gap-4 lg:justify-start">
                    <Link
                      href={slide.primaryCta.href}
                      className="rounded-md bg-white px-6 py-3 text-sm font-medium text-slate-900 shadow-sm transition hover:-translate-y-[1px] hover:bg-slate-100"
                    >
                      {slide.primaryCta.label}
                    </Link>
                    {slide.secondaryCta ? (
                      <Link
                        href={slide.secondaryCta.href}
                        className="rounded-md border border-white/60 px-6 py-3 text-sm font-medium text-white transition hover:-translate-y-[1px] hover:border-white hover:bg-white/10"
                      >
                        {slide.secondaryCta.label}
                      </Link>
                    ) : null}
                  </div>
                </div>

                <div
                  className={cn(
                    "relative hidden overflow-hidden rounded-3xl border border-white/10 bg-white/10 p-6 text-left text-white shadow-[0_50px_80px_-32px_rgba(15,23,42,0.55)] backdrop-blur-lg transition-all duration-700 ease-out lg:block",
                    slideIndex === index
                      ? "pointer-events-auto opacity-100 translate-y-0 scale-100"
                      : "pointer-events-none opacity-0 translate-y-6 scale-95 lg:hidden",
                  )}
                >
                  {renderVisual(slide)}
                  <div className="pointer-events-none absolute -right-10 top-6 h-24 w-24 rounded-full bg-white/10 blur-2xl" />
                  <div className="pointer-events-none absolute -bottom-12 left-8 h-28 w-28 rounded-full bg-indigo-400/30 blur-3xl" />
                </div>
              </article>
            ))}
          </div>
        </div>

        {slideCount > 1 ? (
          <div className="mt-6 flex w-full max-w-3xl items-center justify-between gap-6 lg:max-w-none">
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => setIsPaused((prev) => !prev)}
                className="inline-flex h-9 w-9 items-center justify-center rounded-full border border-white/40 bg-white/10 text-white transition hover:bg-white/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/40"
                aria-label={isPaused ? "Resume autoplay" : "Pause slides"}
              >
                {isPaused ? <Play className="h-4 w-4" /> : <Pause className="h-4 w-4" />}
              </button>
              <button
                type="button"
                onClick={() => goTo(index - 1)}
                className="inline-flex h-9 w-9 items-center justify-center rounded-full border border-white/40 bg-white/10 text-white transition hover:bg-white/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/40"
                aria-label="Previous slide"
              >
                <ChevronLeft className="h-4 w-4" />
              </button>
              <button
                type="button"
                onClick={() => goTo(index + 1)}
                className="inline-flex h-9 w-9 items-center justify-center rounded-full border border-white/40 bg-white/10 text-white transition hover:bg-white/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/40"
                aria-label="Next slide"
              >
                <ChevronRight className="h-4 w-4" />
              </button>
            </div>
            <div className="flex items-center gap-2">
              {safeSlides.map((slide, slideIndex) => (
                <button
                  key={`${slide.id}-dot`}
                  type="button"
                  onClick={() => goTo(slideIndex)}
                  className={cn(
                    "h-2.5 w-2.5 rounded-full transition",
                    slideIndex === index ? "bg-white" : "bg-white/40 hover:bg-white/70",
                  )}
                  aria-label={`Go to slide ${slideIndex + 1}`}
                  aria-current={slideIndex === index}
                />
              ))}
            </div>
          </div>
        ) : null}
      </div>
    </section>
  );
}

function renderVisual(slide: HeroSlide) {
  switch (slide.visual) {
    case "storefront":
      return <StorefrontVisual />;
    case "checkout":
      return <CheckoutVisual />;
    case "delivery":
      return <DeliveryVisual />;
    case "promo":
      return <PromoVisual />;
    case "reviews":
      return <ReviewsVisual />;
    default:
      if (slide.metrics?.length) {
        return (
          <div className="mt-1 grid gap-4">
            {slide.metrics.map((metric) => (
              <div
                key={`${slide.id}-${metric.label}`}
                className="rounded-2xl bg-white/5 p-4 shadow-[0_18px_36px_rgba(14,20,37,0.35)]"
              >
                <div className="text-sm text-white/70">{metric.label}</div>
                <div className="mt-1 text-2xl font-semibold text-white">{metric.value}</div>
                {metric.detail ? <p className="mt-1 text-xs text-white/60">{metric.detail}</p> : null}
              </div>
            ))}
          </div>
        );
      }
      return (
        <p className="text-sm text-white/70">
          Swipe through to see storefront layouts, checkout flow, delivery perks, promo tools, and customer reviews.
        </p>
      );
  }
}

